/* TEST-ONLY: the float FIR listings (HB[2], HB[4]) with FIR_TAPS changed 32 -> 33 and every public name suffixed _odd,
 * generated by textual substitution by the spec script (build_hb_A.py).  Exists only so tests/test_A_fir_float.c can drive the
 * odd-tap-count middle-tap branch of fir_process_symmetric, which is dead code at the book's FIR_TAPS = 32.  Not part of the book. */
#ifndef HBA_FIR_FLOAT_ODD_H
#define HBA_FIR_FLOAT_ODD_H
#define FIR_TAPS_ODD 33

typedef struct {
    float coeffs[FIR_TAPS_ODD];
    float history[FIR_TAPS_ODD];
    int idx;
} fir_filter_t_odd;

static void fir_init_odd(fir_filter_t_odd *f, const float *coeffs) {
    for (int i = 0; i < FIR_TAPS_ODD; i++) {
        f->coeffs[i] = coeffs[i];
        f->history[i] = 0.0f;
    }
    f->idx = 0;
}

static float fir_process_odd(fir_filter_t_odd *f, float input) {
    f->history[f->idx] = input;

    float acc = 0.0f;
    int idx = f->idx;
    for (int i = 0; i < FIR_TAPS_ODD; i++) {
        acc += f->coeffs[i] * f->history[idx];
        idx = (idx == 0) ? FIR_TAPS_ODD - 1 : idx - 1;
    }

    f->idx = (f->idx + 1) % FIR_TAPS_ODD;
    return acc;
}

// Symmetric (linear-phase) FIR: half the multiplies of the direct-form version above.
// Valid only when coeffs[i] == coeffs[FIR_TAPS_ODD - 1 - i] for all i (a linear-phase design).
static float fir_process_symmetric_odd(fir_filter_t_odd *f, float input) {
    f->history[f->idx] = input;

    float acc = 0.0f;
    int i_lo = f->idx;                     // walks newest -> older each step (age 0, 1, 2, ...)
    int i_hi = (f->idx + 1) % FIR_TAPS_ODD;     // walks oldest -> newer each step (age N-1, N-2, ...)
    for (int i = 0; i < FIR_TAPS_ODD / 2; i++) {
        acc += f->coeffs[i] * (f->history[i_lo] + f->history[i_hi]);
        i_lo = (i_lo == 0) ? FIR_TAPS_ODD - 1 : i_lo - 1;
        i_hi = (i_hi == FIR_TAPS_ODD - 1) ? 0 : i_hi + 1;
    }
    if (FIR_TAPS_ODD % 2 == 1) {
        // Odd tap count: the middle tap has no symmetric partner. After the loop above,
        // i_lo has walked down to exactly the center sample's position; add it once, unpaired.
        acc += f->coeffs[FIR_TAPS_ODD / 2] * f->history[i_lo];
    }

    f->idx = (f->idx + 1) % FIR_TAPS_ODD;
    return acc;
}
#endif
